	"Content-Type":"application/x-www-form-urlencoded",
	"Connection":"Keep-Alive",
	"Host":"47.93.18.240",
	"User-Agent":"okhttp/4.9.0"
}
});
	url = "http://47.93.18.240/classifylist.php,"+y;
